CREATE TABLE IF NOT EXISTS lessons (id BIGSERIAL PRIMARY KEY, class_id BIGINT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, subject_id BIGINT NULL REFERENCES subjects(id) ON DELETE SET NULL, teacher_id BIGINT NULL REFERENCES staff(id) ON DELETE SET NULL, date DATE NOT NULL, title TEXT NOT NULL, body TEXT NULL, homework TEXT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lesson_materials (id BIGSERIAL PRIMARY KEY, lesson_id BIGINT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE, filename TEXT NOT NULL, storage_key TEXT NOT NULL, size_bytes BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activities (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'club' CHECK (kind IN ('club','sport','event','service')), description TEXT NULL, supervisor_id BIGINT NULL REFERENCES staff(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS activity_members (id BIGSERIAL PRIMARY KEY, activity_id BIGINT NOT NULL REFERENCES activities(id) ON DELETE CASCADE, student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE, joined_on DATE NOT NULL DEFAULT CURRENT_DATE, UNIQUE (activity_id, student_id));
CREATE INDEX IF NOT EXISTS idx_lessons_class ON lessons (class_id, date);
CREATE INDEX IF NOT EXISTS idx_activity_members_student ON activity_members (student_id);
